// node mods/sotn-ultimate/tools/builder/node/survey_arrays.ts SRC_DIR OBJ_ROOT MAP BIN BASE
// Survey: the generated arrays of a stage (SRC_DIR/gen/** and the
// generated mod_*.h, "Generated by" in their first line), located in the
// built overlay BIN (loaded at BASE) through node/c_arrays.ts, checked byte
// for byte; what is left over (arrays not found, and non-numeric ones).
import * as fs from "node:fs";
import * as path from "node:path";
import { arrayBytes, parseCArrays, symbolAddresses } from "./c_arrays.ts";
import { ROOT } from "./util.ts";

const [srcDir, objRoot, mapFile, binFile, baseHex] = process.argv.slice(2);
const base = parseInt(baseHex, 16);
const bin = new Uint8Array(fs.readFileSync(binFile));
const syms = symbolAddresses(path.join(ROOT, mapFile), path.join(ROOT, objRoot));
const files: string[] = [];
const walk = (d: string): void => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
        const p = path.join(d, e.name);
        if (e.isDirectory()) {
            walk(p);
        } else if (/\.(c|h)$/.test(e.name)) {
            const head = fs.readFileSync(p, "utf8").slice(0, 200);
            if (p.includes("/gen/") || /Generated by/.test(head)) {
                files.push(p);
            }
        }
    }
};
walk(path.join(ROOT, srcDir));
// the retail PS1 stage files: an array found there is the PS1's own data
const ps1: Buffer[] = [];
for (const top of ["ST", "BOSS"]) {
    for (const d of fs.readdirSync(path.join(ROOT, "disks/us", top))) {
        for (const f of fs.readdirSync(path.join(ROOT, "disks/us", top, d))) {
            if (/\.BIN$/i.test(f)) {
                ps1.push(fs.readFileSync(path.join(ROOT, "disks/us", top, d, f)));
            }
        }
    }
}
let ps1Own = 0;
let ps1Bytes = 0;
let found = 0;
let bytes = 0;
const missing: string[] = [];
const seen = new Set<string>();
for (const f of files) {
    let arrays;
    try {
        arrays = parseCArrays(f, [path.join(ROOT, srcDir), path.join(ROOT, "include")]);
    } catch (e) {
        missing.push(path.relative(ROOT, f) + ": " + e);
        continue;
    }
    for (const a of arrays) {
        if (seen.has(a.name)) {
            continue;
        }
        seen.add(a.name);
        const want = arrayBytes(a);
        const at = (syms.get(a.name) ?? []).map((x) => x - base).find((o) =>
            o >= 0 && o + want.length <= bin.length && want.every((b, i) => bin[o + i] === b));
        if (at === undefined) {
            missing.push(a.name + " (" + path.relative(ROOT, f) + ", " + want.length + " bytes)");
            continue;
        }
        found++;
        bytes += want.length;
        if (want.length >= 16 && ps1.some((b) => b.indexOf(want) >= 0)) {
            ps1Own++;
            ps1Bytes += want.length;
        }
    }
}
console.log("%d generated files, %d arrays located (%d bytes), %d not; PS1's own (verbatim in disks/us): %d arrays, %d bytes",
            files.length, found, bytes, missing.length, ps1Own, ps1Bytes);
for (const m of missing.slice(0, 40)) {
    console.log("  " + m);
}
